const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the local index.html
  const filePath = 'file://' + path.resolve('index.html');
  await page.goto(filePath);

  // Inject axe
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe on the initial page
  let results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  console.log('--- Initial Page Results ---');
  reportResults(results);

  // Open the dialog and run axe again
  await page.click('.trigger');
  // Wait a bit for any transitions
  await page.waitForTimeout(500);

  results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  console.log('--- Dialog Open Results ---');
  reportResults(results);

  await browser.close();
})();

function reportResults(results) {
  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
